// ============================================
// FILTER MCP-* WORKFLOWS AND BUILD REGISTRY
// ============================================

const response = $input.first().json;
const workflows = response.data || response;

// Filter MCP-* workflows only
const mcpWorkflows = workflows.filter(wf => 
  wf.name && wf.name.startsWith('MCP') && wf.active
);

// Build tools registry
const tools = mcpWorkflows.map(wf => {
  // Extract tool info from workflow name
  // MCP - Transcriber → mcp_transcriber
  // MCP-Image-Generator → mcp_image_generator
  const toolName = 'mcp_' + wf.name
    .replace(/^MCP\s*-\s*/, '')
    .replace(/\s+/g, '_')
    .replace(/-/g, '_')
    .toLowerCase();

  // Try to extract description from sticky note or first node
  let description = `Workflow ${wf.name}`;
  let parameters = {};
  let metadata = {
    webhook_path: `/webhook/mcp/${wf.name.replace(/^MCP\s*-\s*/, '').replace(/\s+/g, '-').toLowerCase()}`,
    async: false,
    timeout_seconds: 30,
    workflow_id: wf.id,
    workflow_name: wf.name
  };

  // Check if workflow has nodes with documentation
  if (wf.nodes && Array.isArray(wf.nodes)) {
    // Find sticky note with documentation
    const stickyNote = wf.nodes.find(n => 
      n.type === 'n8n-nodes-base.stickyNote' && 
      n.parameters?.content
    );

    if (stickyNote) {
      const content = stickyNote.parameters.content;
      // Extract description from sticky note
      const descMatch = content.match(/\*\*Description:\*\*\s*([^\n]+)/i);
      if (descMatch) {
        description = descMatch[1].trim();
      }
    }

    // Find webhook node to get actual path
    const webhookNode = wf.nodes.find(n => 
      n.type === 'n8n-nodes-base.webhook'
    );

    if (webhookNode && webhookNode.parameters?.path) {
      metadata.webhook_path = `/webhook/${webhookNode.parameters.path}`;
    }

    // Check for async indicators
    if (wf.nodes.some(n => 
      n.name?.toLowerCase().includes('callback') ||
      n.name?.toLowerCase().includes('async')
    )) {
      metadata.async = true;
      metadata.timeout_seconds = 120;
    }
  }

  // Basic parameters schema (can be enhanced per workflow)
  parameters = {
    type: 'object',
    properties: {
      input: { type: 'string', description: 'Input data for the tool' }
    },
    required: []
  };

  return {
    name: toolName,
    description: description,
    parameters: parameters,
    metadata: metadata
  };
});

// Exclude this registry workflow and notify workflow
const filteredTools = tools.filter(t => 
  !t.name.includes('registry') && 
  !t.name.includes('notify') &&
  !t.name.includes('watcher')
);

return {
  version: '1.0',
  updated_at: new Date().toISOString(),
  count: filteredTools.length,
  tools: filteredTools
};
